 sents:[["他/正在/学习。", "tā/zhèng|zài/xué|xí.", "เขากำลังเรียนอยู่"], ["他/正在/睡觉。", "tā/zhèng|zài/shuì|jiào.", "เขากำลังนอนอยู่"], ["他/正在/工作。", "tā/zhèng|zài/gōng|zuò.", "เขากำลังทำงานอยู่"], ["他/向/我/走/来。", "tā/xiàng/wǒ/zǒu/lái.", "เขาเดินมาทางฉัน"], ["他/坐/着/看/书。", "tā/zuò/zhe/kàn/shū.", "เขานั่งอ่านหนังสืออยู่"], ["这/个/是/为/你/买/的。", "zhè/ge/shì/wèi/nǐ/mǎi/de.", "อันนี้ซื้อมาให้คุณ"]],
